import{_ as e,o as i,c as l,a4 as o}from"./chunks/framework.BRzJ4ijD.js";const p=JSON.parse('{"title":"第四部分 · 数据库系统","description":"","frontmatter":{},"headers":[],"relativePath":"databases/index.md","filePath":"databases/README.md","lastUpdated":1788475713000}'),r={name:"databases/index.md"};function t(n,a,s,h,d,c){return i(),l("div",null,[...a[0]||(a[0]=[o('<h1 id="第四部分-·-数据库系统" tabindex="-1">第四部分 · 数据库系统 <a class="header-anchor" href="#第四部分-·-数据库系统" aria-label="Permalink to &quot;第四部分 · 数据库系统&quot;">​</a></h1><h2 id="一句话" tabindex="-1">一句话 <a class="header-anchor" href="#一句话" aria-label="Permalink to &quot;一句话&quot;">​</a></h2><p>数据库是把&quot;对状态的可恢复变更&quot;这件事以最强形式封装起来的产品——从存储引擎 (B+ tree / LSM) 到查询优化 (RBO/CBO)，从 ACID 隔离 (2PL/MVCC/SSI) 到崩溃恢复 (WAL/ARIES)，从单机 (Postgres/MySQL) 到分布式 (Spanner/CockroachDB)，从 OLTP 到 OLAP 列存 (ClickHouse/Snowflake/DuckDB)。理解数据库 = 理解工程理想与现实约束的对撞。</p><h2 id="这一部分的结构" tabindex="-1">这一部分的结构 <a class="header-anchor" href="#这一部分的结构" aria-label="Permalink to &quot;这一部分的结构&quot;">​</a></h2><h3 id="_1-sql-与关系模型" tabindex="-1">1. SQL 与关系模型 <a class="header-anchor" href="#_1-sql-与关系模型" aria-label="Permalink to &quot;1. SQL 与关系模型&quot;">​</a></h3><p>关系代数是 SQL 的内核，planner 把 SQL 解析为代数表达式再做 rule-based + cost-based 转换。理解 NULL 三值逻辑、CTE decorrelation、window sort/agg、子查询代数变换是阅读 query plan 的前提。</p><ul><li><a href="./relational/relational">关系代数、SQL semantics</a></li><li><a href="./relational/isolation">事务、ACID、隔离级别与现象</a></li><li><a href="./relational/mvcc">MVCC 原理：PostgreSQL vs InnoDB</a></li><li><a href="./relational/wal-2pl">WAL / redo / undo / 2PL</a></li></ul><h3 id="_2-索引与存储结构" tabindex="-1">2. 索引与存储结构 <a class="header-anchor" href="#_2-索引与存储结构" aria-label="Permalink to &quot;2. 索引与存储结构&quot;">​</a></h3><p>B+ tree 与 LSM 是两条主流路径：B+ tree 适合读多写少（OLTP），LSM 适合写多读少（time series, ClickHouse-ish SST）。两者都有写放大、读放大、空间放大的折中。</p><ul><li><a href="./indexing/btree">B+ 树索引与覆盖索引</a></li><li><a href="./indexing/lsm">LSM-Tree 与 SSTable</a></li><li><a href="./indexing/specialized">Hash index、GIN、GiST、BRIN</a></li><li><a href="./indexing/explain">执行计划：explain analyze 怎么读</a></li></ul><h3 id="_3-日志与崩溃恢复" tabindex="-1">3. 日志与崩溃恢复 <a class="header-anchor" href="#_3-日志与崩溃恢复" aria-label="Permalink to &quot;3. 日志与崩溃恢复&quot;">​</a></h3><p>WAL（redo log）+ undo log 让数据库在崩溃后能 redo 重做已提交、undo 回滚未提交。ARIES 是工业级 WAL 协议设计，被 Postgres/MySQL/SQL Server/Oracle 全部遵守。</p><ul><li><a href="./recovery/aries">WAL 协议、ARIES</a></li><li><a href="./recovery/checkpoint">Checkpoint、Point-in-time 恢复</a></li></ul><h3 id="_4-查询优化" tabindex="-1">4. 查询优化 <a class="header-anchor" href="#_4-查询优化" aria-label="Permalink to &quot;4. 查询优化&quot;">​</a></h3><p>planner 选择 join 顺序、join 算法（hash/merge/nested loop）、向量化执行、列存格式——是数据库&quot;不写代码也跑得快&quot;的核心。</p><ul><li><a href="./optimization/rbo-cbo">基于规则 / 基于代价优化</a></li><li><a href="./optimization/join">Join 顺序、hash join vs nested loop</a></li><li><a href="./optimization/vectorized">向量化执行、列存</a></li></ul><h3 id="_5-olap-与现代数据栈" tabindex="-1">5. OLAP 与现代数据栈 <a class="header-anchor" href="#_5-olap-与现代数据栈" aria-label="Permalink to &quot;5. OLAP 与现代数据栈&quot;">​</a></h3><p>列存 + 向量化执行 + 物化视图 + Lakehouse (Iceberg/Delta/Hudi) 是过去十年数据栈演进总结。</p><ul><li><a href="./olap/columnar">ClickHouse / DuckDB / Snowflake 设计</a></li><li><a href="./olap/materialized">预聚合、物化视图、Cubes</a></li><li><a href="./olap/lakehouse">Lakehouse：Iceberg / Delta / Hudi</a></li></ul><hr><h2 id="读完你应该能回答" tabindex="-1">读完你应该能回答 <a class="header-anchor" href="#读完你应该能回答" aria-label="Permalink to &quot;读完你应该能回答&quot;">​</a></h2><ul><li>为什么不能把 MVCC tid 直接当 row id</li><li>InnoDB 与 PostgreSQL MVCC 的 vacuum 性能差异</li><li>LSM Tree 与 B+ Tree 在 update 吞吐与读放大上的权衡</li><li>ARIES 的 redo-only undo 设计到底是为了什么</li><li>列存为什么对 SIMD + cache 友好</li><li>为什么 Postgres 不用 MySQL 的 gap lock 防止 phantom (改用 SSI)</li><li>DuckDB 与 Postgres 在 OLAP 100GB 查询上的 100x 性能差来源</li><li>Iceberg 在大数据生态里到底解决了什么——为什么取代 Hive Metastore 是平滑过渡</li></ul>',22)])])}const S=e(r,[["render",t]]);export{p as __pageData,S as default};
